9287f7ca:  ;
 ;Calculate the number of days overdue on a record in the
 ;MEDICAL TRANSCRIPTION status file.
 ;

830eb231:  ;
 ;If the status is 'INCOMPLETE' then check
 ;the number of days since the Expected Signature Date.
 ;If current date is beyond that date, set flag and days late.
 ;

7fd11e82:  ;
 ;If the status is 'DICTATED' then set the flag
 ;and calculate the number of days late.
 ;

34ccf893:  ;
 ;If the status is 'TRANSCRIBED' then check the number of
 ;days since the Expected Dictation Date.
 ;If current date is beyond that date, set flag and days late.
 ;

f7bc5aff:  ;
 ;If there is an Expected Signature Date
 ;and the status is 'SIGNED' then check the number
 ;of days beyond the Expected Signature Date.
 ;If current date is beyond that date, set flag and days late.
 ;
